from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_dates = set()

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # Consolidator is aligned to clock boundaries: regular-session first bar ends at 09:35.
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if prior_fast is not None and prior_slow is not None:
            self.previous_fast = prior_fast
            self.previous_slow = prior_slow

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = bar.EndTime
        if not (bar_time.hour > 9 or (bar_time.hour == 9 and bar_time.minute >= 45)):
            return
        if not (bar_time.hour < 14 or (bar_time.hour == 14 and bar_time.minute <= 30)):
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        self.TryEnter(bar_time)

    def TryEnter(self, signal_time):
        if signal_time.date() in self.no_entry_dates:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        if self.Portfolio[self.spy].Invested:
            return

        current_slice = self.CurrentSlice
        if current_slice is None or self.option_canonical not in current_slice.OptionChains:
            self.Debug(f"{signal_time}: Entry skipped: no SPY option chain.")
            return

        chain = current_slice.OptionChains[self.option_canonical]
        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{signal_time}: Entry skipped: invalid SPY price.")
            return

        min_expiry_date = signal_time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= min_expiry_date
        })

        if not expiries:
            self.Debug(f"{signal_time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{signal_time}: Entry skipped: no qualifying call at selected expiration.")
            return

        contract = sorted(candidates, key=lambda c: (c.Strike, str(c.Symbol)))[0]

        self.held_contract = contract.Symbol
        self.held_expiry = contract.Expiry
        self.entry_price = None
        self.exit_ticket = None
        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)

        self.Debug(
            f"{signal_time}: Entering 1 SPY call {contract.Symbol}, "
            f"expiry {contract.Expiry.date()}, strike {contract.Strike}."
        )

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity

        # Never intentionally hold through expiration.
        if self.Time.date() >= self.held_expiry.date():
            self.no_entry_dates.add(self.Time.date())
            if quantity != 0 and not self.IsOpen(self.exit_ticket):
                self.CancelOpenExitOrder()
                self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
                self.Debug(f"{self.Time}: Expiration processing exit for {self.held_contract}.")
            return

        if quantity == 0 or self.entry_price is None:
            return

        # Time stop: 15:45 on the trading day immediately before expiration.
        prior_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousMarketOpen(
            self.held_expiry, False
        ).date()

        if self.Time.date() == prior_trading_day and self.Time.hour == 15 and self.Time.minute == 45:
            if not self.IsOpen(self.exit_ticket):
                self.CancelOpenExitOrder()
                self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
                self.Debug(f"{self.Time}: Pre-expiration time-stop exit for {self.held_contract}.")
            return

        if self.IsOpen(self.exit_ticket):
            return

        quote_contract = self.FindContractInSlice(slice, self.held_contract)
        if quote_contract is None:
            return

        bid = quote_contract.BidPrice
        ask = quote_contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
            self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
            self.Debug(
                f"{self.Time}: Profit-target exit for {self.held_contract}; "
                f"midpoint={midpoint:.2f}, entry={self.entry_price:.2f}."
            )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled] and order_event.FillQuantity > 0:
                if self.entry_price is None:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"{self.Time}: Entry filled for {self.held_contract} "
                        f"at {self.entry_price:.2f}."
                    )

            if order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order {order_event.Status} for {self.held_contract}.")
                if self.Portfolio[self.held_contract].Quantity == 0:
                    self.ClearPositionState()

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled for {self.held_contract}.")
                self.ClearPositionState()

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        open_spy_orders = self.Transactions.GetOpenOrders(self.spy)
        if len(open_spy_orders) == 0:
            self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

    def FindContractInSlice(self, slice, symbol):
        if self.option_canonical not in slice.OptionChains:
            return None

        for contract in slice.OptionChains[self.option_canonical]:
            if contract.Symbol == symbol:
                return contract
        return None

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        ]

    def ClearPositionState(self):
        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
