from collections import deque
from datetime import time, timedelta

from QuantConnect import (
    DataNormalizationMode,
    OptionRight,
    OrderStatus,
    Resolution,
    TimeZones,
)
from QuantConnect.Algorithm import QCAlgorithm


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(
                timedelta(0), timedelta(days=730)
            )
        )

        # These are warmed only by bars received during the requested backtest.
        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        # Manual five-minute aggregation state. A valid interval requires all
        # five constituent minute bars, ending at 09:35, 09:40, etc.
        self.current_bucket_end = None
        self.bucket_bars = []

        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_liquidation_order_id = None

        self.held_contract = None
        self.entry_fill_price = None
        self.held_expiry_date = None
        self.pre_expiry_trading_date = None
        self.no_reentry_date = None

    def OnData(self, data):
        self._handle_unexpected_spy_position()
        self._handle_option_exits(data)

        if not data.Bars.ContainsKey(self.spy):
            return

        bar = data.Bars[self.spy]
        end_time = bar.EndTime

        # SPY is subscribed with regular market hours, but retain this guard so
        # only regular-session five-minute bars affect the moving averages.
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        bucket_end = self._five_minute_bucket_end(end_time)

        # If the prior bucket did not receive all required minute bars, discard
        # it without updating either moving average.
        if self.current_bucket_end is not None and bucket_end != self.current_bucket_end:
            self.current_bucket_end = bucket_end
            self.bucket_bars = []

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end

        self.bucket_bars.append(bar)

        # A completed five-minute bar is evaluated immediately when its final
        # constituent minute bar arrives.
        if end_time == self.current_bucket_end:
            completed = self._valid_completed_bucket(end_time)

            if completed:
                self._on_five_minute_close(end_time, bar.Close, data)

            self.current_bucket_end = None
            self.bucket_bars = []

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id:
                self.entry_fill_price = order_event.FillPrice
                self.held_contract = order_event.Symbol
                self.held_expiry_date = order_event.Symbol.ID.Date.date()
                self.pre_expiry_trading_date = self._previous_trading_day(
                    order_event.Symbol.ID.Date
                )
                self.entry_order_id = None

                self.Debug(
                    f"ENTRY FILLED {self.held_contract} @ {self.entry_fill_price:.2f}"
                )
                return

            if order_event.OrderId == self.exit_order_id:
                self.Debug(
                    f"EXIT FILLED {order_event.Symbol} @ {order_event.FillPrice:.2f}"
                )
                self.exit_order_id = None
                self._clear_option_state()
                return

            if order_event.OrderId == self.spy_liquidation_order_id:
                self.Debug(
                    f"Unexpected SPY position liquidated @ {order_event.FillPrice:.2f}"
                )
                self.spy_liquidation_order_id = None
                return

        if order_event.OrderId == self.entry_order_id and self._is_terminal(order_event.Status):
            self.entry_order_id = None
            self.Debug(f"ENTRY ORDER CLOSED WITHOUT FILL: {order_event.Status}")

        if order_event.OrderId == self.exit_order_id and self._is_terminal(order_event.Status):
            self.exit_order_id = None

        if (
            order_event.OrderId == self.spy_liquidation_order_id
            and self._is_terminal(order_event.Status)
        ):
            self.spy_liquidation_order_id = None

    def _on_five_minute_close(self, end_time, close, data):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        current_fast = sum(values[-5:]) / 5.0
        current_slow = sum(values) / 20.0

        bullish_cross = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)
        if bullish_cross and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data):
        if self.Time.date() == self.no_reentry_date:
            return

        if self.held_contract is not None or self._has_open_entry_order():
            return

        if self.Portfolio[self.spy].Invested:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("ENTRY SKIPPED: no SPY option chain in current Slice")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("ENTRY SKIPPED: invalid SPY price")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("ENTRY SKIPPED: no expiration at least 7 calendar days away")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"ENTRY SKIPPED: no qualifying call for expiry {selected_expiry}"
            )
            return

        contract = min(candidates, key=lambda x: (x.Strike, str(x.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1, tag="Bullish 5m MA crossover")
        self.entry_order_id = ticket.OrderId

        self.Debug(
            f"ENTRY SUBMITTED: {contract.Symbol}, strike {contract.Strike}, "
            f"expiry {contract.Expiry.date()}"
        )

    def _handle_option_exits(self, data):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self._clear_option_state()
            return

        # Never intentionally carry the contract into its expiration date.
        if self.Time.date() >= self.held_expiry_date:
            self.no_reentry_date = self.Time.date()
            self._submit_option_exit("Expiration safety liquidation")
            return

        # Time stop on the exchange trading day immediately before expiration.
        if (
            self.Time.date() == self.pre_expiry_trading_date
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_option_exit("15:45 pre-expiration liquidation")
            return

        if self._has_open_exit_order():
            return

        if not data.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = data.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_fill_price is not None and midpoint >= 1.50 * self.entry_fill_price:
            self._submit_option_exit("50% midpoint profit target")

    def _submit_option_exit(self, reason):
        if self.held_contract is None or self._has_open_exit_order():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self._clear_option_state()
            return

        # Ensure no competing exit remains before placing this market order.
        self.Transactions.CancelOpenOrders(self.held_contract)
        ticket = self.MarketOrder(self.held_contract, -quantity, tag=reason)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"EXIT SUBMITTED: {self.held_contract} ({reason})")

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self._has_open_spy_liquidation_order():
            return

        quantity = self.Portfolio[self.spy].Quantity
        ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise/assignment SPY liquidation"
        )
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"UNEXPECTED EXERCISE/ASSIGNMENT: liquidating {quantity} SPY shares"
        )

    def _five_minute_bucket_end(self, end_time):
        session_open_minutes = 9 * 60 + 30
        current_minutes = end_time.hour * 60 + end_time.minute
        elapsed = current_minutes - session_open_minutes
        bucket_minutes = ((elapsed + 4) // 5) * 5

        return end_time.replace(
            hour=(session_open_minutes + bucket_minutes) // 60,
            minute=(session_open_minutes + bucket_minutes) % 60,
            second=0,
            microsecond=0
        )

    def _valid_completed_bucket(self, end_time):
        if len(self.bucket_bars) != 5:
            return False

        expected = end_time - timedelta(minutes=4)
        for bar in self.bucket_bars:
            if bar.EndTime != expected:
                return False
            expected += timedelta(minutes=1)

        return True

    def _previous_trading_day(self, expiry):
        candidate = expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _has_open_entry_order(self):
        return self._order_is_open(self.entry_order_id)

    def _has_open_exit_order(self):
        return self._order_is_open(self.exit_order_id)

    def _has_open_spy_liquidation_order(self):
        return self._order_is_open(self.spy_liquidation_order_id)

    def _order_is_open(self, order_id):
        if order_id is None:
            return False

        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _is_terminal(self, status):
        return status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Filled,
        )

