        option.SetFilter(-200, 200, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.pending_crossover_time = None
        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.expiration_block_date = None
        self.equity_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.AfterMarketOpen(self.spy, 0),
            self._expiration_guard
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self._time_stop
        )

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        # The consolidator marks a crossover; selection happens here using this
        # exact bar-close Slice and its option chain.
        if self.pending_crossover_time is not None:
            signal_time = self.pending_crossover_time
            self.pending_crossover_time = None

            if signal_time == self.Time:
                self._try_enter(data)

        self._check_profit_target(data)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        had_ready_averages = self.fast.IsReady and self.slow.IsReady
        prior_fast = self.fast.Current.Value if had_ready_averages else None
        prior_slow = self.slow.Current.Value if had_ready_averages else None

        # Only actual consolidator output updates the averages.
        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if not had_ready_averages or not (self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            prior_fast <= prior_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self.pending_crossover_time = bar.EndTime

    def _try_enter(self, data: Slice):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_contract is not None or self._entry_order_is_open():
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{self.Time}: Entry skipped: no current SPY price.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no option chain in Slice.")
            return

        min_expiry_date = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= min_expiry_date
        })

        if not expirations:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no qualifying call for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId

        self.Debug(
            f"{self.Time}: Entry submitted: {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

