        if len(bars) != 5 or not self._is_complete_minute_sequence(bars, self._bucket_end):
            return

        self._on_completed_five_minute_bar(self._bucket_end, bars[-1].Close, data)

    def _five_minute_bucket_end(self, time_value):
        day_start = datetime(time_value.year, time_value.month, time_value.day)
        minutes = time_value.hour * 60 + time_value.minute
        rounded_minutes = ((minutes + 4) // 5) * 5
        return day_start + timedelta(minutes=rounded_minutes)

    def _is_complete_minute_sequence(self, bars, bucket_end):
        expected_first_end = bucket_end - timedelta(minutes=4)
        for index, bar in enumerate(bars):
            if bar.EndTime != expected_first_end + timedelta(minutes=index):
                return False
        return True

    def _on_completed_five_minute_bar(self, bar_end, close, data: Slice):
        self._five_minute_closes.append(float(close))
        if len(self._five_minute_closes) > 21:
            self._five_minute_closes.pop(0)

        # Twenty-one observations are required because both current and preceding
        # 20-bar slow averages must exist for crossover testing.
        if len(self._five_minute_closes) < 21:
            return

        values = self._five_minute_closes
        previous_fast = sum(values[-6:-1]) / 5.0
        previous_slow = sum(values[:-1]) / 20.0
        current_fast = sum(values[-5:]) / 5.0
        current_slow = sum(values[-20:]) / 20.0

        bullish_crossover = (
            previous_fast <= previous_slow and current_fast > current_slow
        )
        entry_time_eligible = (
            datetime.strptime("09:45", "%H:%M").time()
            <= bar_end.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        if bullish_crossover and entry_time_eligible:
            self._try_enter_call(data)

    def _try_enter_call(self, data: Slice):
        if self._no_entries_on == self.Time.date():
            return

        if self._held_symbol is not None or self._entry_order_is_open():
            return

        chain = data.OptionChains.get(self.option_symbol, None)
        spy_bar = data.Bars.get(self.spy, None)

        if chain is None or spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{self.Time}: Entry skipped: no current option chain or SPY price.")
            return

        today = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days >= 7
        })

        if not eligible_expirations:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = float(spy_bar.Close) * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no qualifying call for {selected_expiry}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self._held_symbol = selected.Symbol
        self._held_expiry = selected.Expiry
        self._entry_fill_price = None
        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"{self.Time}: Submitted entry for {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike}."
        )

    def _handle_profit_target(self, data: Slice):
        if self._exit_order_is_open() or self._entry_fill_price is None:
            return

        quote_bar = data.QuoteBars.get(self._held_symbol, None)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = float(quote_bar.Bid.Close)
        ask = float(quote_bar.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_exit("profit target")

    def _handle_time_stop(self):
        if self._exit_order_is_open() or self._held_expiry is None:
            return

        previous_trading_day = self.Securities[
            self.spy
        ].Exchange.Hours.GetPreviousTradingDay(self._held_expiry)

        if (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration(self, data: Slice):
        if self._held_expiry is None or self._exit_order_is_open():
            return

        if self.Time.date() >= self._held_expiry.date():
            self._no_entries_on = self.Time.date()
            self.Debug(
                f"{self.Time}: Expiration handling for {self._held_symbol}; liquidating."
            )
            self._submit_exit("expiration handling")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_other_open_exit_orders()
        self._exit_ticket = self.MarketOrder(self._held_symbol, -quantity)
        self.Debug(f"{self.Time}: Submitted exit for {self._held_symbol}: {reason}.")

    def _cancel_other_open_exit_orders(self):
        if self._held_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self._held_symbol):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

    def _entry_order_is_open(self):
        return self._entry_ticket is not None and self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _exit_order_is_open(self):
        return self._exit_ticket is not None and self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _liquidate_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0:
            return

        if not self.Transactions.GetOpenOrders(self.spy):
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment position; liquidating."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self._entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: Entry filled for {order_event.Symbol} "
                    f"at {self._entry_fill_price}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order did not complete for {order_event.Symbol}.")
                self._clear_option_state()

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
                self._clear_option_state()
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_ticket = None

    def _clear_option_state(self):
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._held_expiry = None
        self._entry_fill_price = None

