from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        self.option_symbol = self.add_option("SPY", Resolution.MINUTE).symbol
        self.option = self.securities[self.option_symbol]
        self.option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-200, 200)
            .expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

    def on_data(self, data: Slice):
        # Immediately flatten unexpected stock created by exercise/assignment.
        if self.portfolio[self.spy].invested:
            self.debug(f"Unexpected SPY exercise/assignment handling at {self.time}")
            self.liquidate(self.spy)

        if self.held_contract is None:
            return

        # Never intentionally hold into expiration.
        if self.time.date() >= self.held_expiry:
            self.no_entry_date = self.time.date()
            self._submit_exit("expiration safety")
            return

        # Mandatory exit at 15:45 on the prior trading day.
        if (self.time.hour, self.time.minute) == (15, 45):
            if self.time.date() == self._previous_spy_trading_day(self.held_expiry):
                self._submit_exit("pre-expiration time stop")
                return

        # Profit target only uses a positive current bid/ask from this Slice.
        if self.entry_fill_price is None or self._exit_order_open():
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (x for x in chain if x.symbol == self.held_contract),
            None
        )
        if contract is None:
            return

        bid = float(contract.bid_price)
        ask = float(contract.ask_price)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._cancel_open_exit_order()
            self._submit_exit("50% profit target")

    def _on_five_minute_bar(self, bar: TradeBar):
        # With regular-hours minute equity data, the first bar ends at 09:35.
        end_time = bar.end_time
        if end_time.minute % 5 != 0 or end_time.second != 0:
            return

        previous_ready = self.fast.is_ready and self.slow.is_ready
        previous_fast = float(self.fast.current.value) if previous_ready else None
        previous_slow = float(self.slow.current.value) if previous_ready else None

        self.fast.update(end_time, bar.close)
        self.slow.update(end_time, bar.close)

        if not previous_ready or not (self.fast.is_ready and self.slow.is_ready):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and float(self.fast.current.value) > float(self.slow.current.value)
        )
        if not bullish_cross:
            return

        if not ((end_time.hour, end_time.minute) >= (9, 45)
                and (end_time.hour, end_time.minute) <= (14, 30)):
            return

        if self.no_entry_date == self.time.date():
            return

        if self.held_contract is not None or self._entry_order_open():
            return

        self._enter_from_current_chain()

    def _enter_from_current_chain(self):
        chain = self.current_slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug(f"Skipped entry {self.time}: no SPY option chain")
            return

        underlying_price = float(self.securities[self.spy].price)
        if underlying_price <= 0:
            self.debug(f"Skipped entry {self.time}: invalid SPY price")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        ]
        if not calls:
            self.debug(f"Skipped entry {self.time}: no eligible call expiration")
            return

        expiry = min(contract.expiry.date() for contract in calls)
        strike_floor = 1.01 * underlying_price
        candidates = [
            contract for contract in calls
            if contract.expiry.date() == expiry
            and float(contract.strike) >= strike_floor
        ]
        if not candidates:
            self.debug(f"Skipped entry {self.time}: no eligible strike at {expiry}")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.strike), str(contract.symbol))
        )

        ticket = self.market_order(selected.symbol, 1)
        self.entry_order_id = ticket.order_id
        self.debug(
            f"Entry submitted {self.time}: {selected.symbol}, "
            f"expiry={expiry}, strike={selected.strike}"
        )

    def on_order_event(self, order_event: OrderEvent):
        if order_event.order_id == self.entry_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.held_contract = order_event.symbol
                self.held_expiry = order_event.symbol.id.date.date()
                self.entry_fill_price = float(order_event.fill_price)
                self.entry_order_id = None
                self.debug(
                    f"Entry filled {self.time}: {order_event.symbol} "
                    f"at {self.entry_fill_price}"
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.debug(f"Entry canceled/invalid {self.time}: {order_event.symbol}")
                self.entry_order_id = None

        elif order_event.order_id == self.exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"Exit filled {self.time}: {order_event.symbol} "
                    f"at {order_event.fill_price}"
                )
                self.exit_order_id = None
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.exit_order_id = None

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self._exit_order_open():
            return

        quantity = self.portfolio[self.held_contract].quantity
        if quantity == 0:
            return

        ticket = self.market_order(self.held_contract, -quantity)
        self.exit_order_id = ticket.order_id
        self.debug(f"Exit submitted {self.time}: {reason}, {self.held_contract}")

    def _entry_order_open(self):
        return self._order_is_open(self.entry_order_id)

    def _exit_order_open(self):
        return self._order_is_open(self.exit_order_id)

    def _order_is_open(self, order_id):
        if order_id is None:
            return False

        ticket = self.transactions.get_order_ticket(order_id)
        if ticket is None:
            return False

        return ticket.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED
        )

    def _cancel_open_exit_order(self):
        if self._exit_order_open():
            self.transactions.get_order_ticket(self.exit_order_id).cancel()

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.securities[self.spy].exchange.hours

        while not hours.is_date_open(candidate, extended_market_hours=False):
            candidate -= timedelta(days=1)

        return candidate
